import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;
import sailpoint.object.Application;
import sailpoint.object.Link;

String APP_NAME = "HR Authoritative CSV";

Date parseDate(Object value) {
    if (value == null) return null;
    String s = value.toString().trim();
    if (s.length() == 0) return null;
    try {
        SimpleDateFormat f = new SimpleDateFormat("dd-MM-yyyy");
        f.setLenient(false);
        return f.parse(s);
    } catch (Exception e) {
        log.error("HR Lifecycle - " + identity.getName() + ": invalid date '" + s + "'");
        return null;
    }
}

// Read the dates from the HR account; fall back to the identity attributes
Object startValue = null;
Object endValue = null;
Application app = context.getObjectByName(Application.class, APP_NAME);
Link hr = (app == null) ? null : identity.getLink(app);
if (hr != null) {
    startValue = hr.getAttribute("startDate");
    endValue   = hr.getAttribute("endDate");
} else {
    startValue = identity.getAttribute("startDate");
    endValue   = identity.getAttribute("endDate");
}

Date start = parseDate(startValue);
Date end   = parseDate(endValue);

// Midnight today, so comparisons are by whole day
Calendar cal = Calendar.getInstance();
cal.set(Calendar.HOUR_OF_DAY, 0);
cal.set(Calendar.MINUTE, 0);
cal.set(Calendar.SECOND, 0);
cal.set(Calendar.MILLISECOND, 0);
Date today = cal.getTime();

// A past end date wins, even over Emergency Disable
if (end != null && end.before(today)) {
    return "Terminated";
}

// Emergency Disable overrides PreHire and Active
Object emergency = identity.getAttribute("emergencyDisable");
if (emergency != null && "true".equalsIgnoreCase(emergency.toString().trim())) {
    return "Disabled";
}

// No HR data at all: keep whatever we had before, but never a stale Disabled
if (start == null && end == null) {
    return "Disabled".equals(oldValue) ? null : oldValue;
}

if (start != null && start.after(today)) {
    return "PreHire";
}
return "Active";
